pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz the EOA that will be the transaction origin and the newOwner address to set.
    // We must provide at least one fuzz param. The difference manifests when the call to setOwner
    // is made through an intermediate contract: msg.sender != tx.origin. The fuzzer supplies
    // the EOA (actor) and the candidate new owner.
    function testFuzz_property(address actor, address candidateNewOwner) public {
        // keep addresses in their wide domains but not zero for clarity
        vm.assume(actor != address(0));
        vm.assume(candidateNewOwner != address(0));

        // The reference contract's onlyOwner requires msg.sender == owner.
        // To show the property universally: if an EOA (actor) is the owner and calls setOwner
        // directly (msg.sender == tx.origin == actor) then setOwner succeeds and sets owner.
        // However the difference with tx.origin appears when a contract intermediary calls setOwner:
        // under reference, only the intermediary contract (msg.sender) must be owner; under mutant,
        // tx.origin is checked so if the origin EOA is owner the intermediary contract can change owner
        // even though msg.sender != owner.

        // 1) Make 'actor' the owner by having it call on its own (prank) to setOwner to itself.
        // This establishes actor as owner on the reference implementation.
        vm.prank(address(this));
        // The deployer (this test contract) is initial owner; make owner = actor by direct call from deployer
        // i.e., call setOwner(actor) as the deployer (owner) to set owner to actor.
        c.setOwner(actor);

        // 2) Deploy an intermediary contract that will call c.setOwner(candidateNewOwner).
        // The intermediary will execute the call with msg.sender = address(intermediary) and tx.origin = actor
        // because we will make the EOA 'actor' be the tx.origin by using vm.prank(actor) when invoking the intermediary.
        Intermediary intermediary = new Intermediary(c);

        // 3) Have the EOA 'actor' (who is the current owner in the reference) call the intermediary, which in turn
        // calls c.setOwner(candidateNewOwner). This produces msg.sender == address(intermediary) and tx.origin == actor.
        vm.prank(actor);
        intermediary.callSetOwner(candidateNewOwner);

        // Single assertion: On the correct contract, since onlyOwner uses msg.sender, the intermediary (msg.sender)
        // is not equal to the owner (actor), so the call must have been rejected and owner remains actor.
        // On the mutant (checking tx.origin) the call would succeed because tx.origin == actor, so owner would
        // become candidateNewOwner for some inputs — thus the single assertion distinguishes them.
        assertTrue(c.owner() == actor);
    }
}

// Minimal intermediary that simply forwards the setOwner call to the target contract.
contract Intermediary {
    C target;
    constructor(C _target) { target = _target; }
    function callSetOwner(address _newOwner) external {
        target.setOwner(_newOwner);
    }
}

