pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: an EOA ownerCandidate and a newOwner to attempt to set
    function testFuzz_property(address ownerCandidate, address newOwner) public {
        // keep inputs meaningful: not zero addresses for owner/newOwner to avoid trivialities
        vm.assume(ownerCandidate != address(0));
        vm.assume(newOwner != address(0));

        // Deploy an attacker contract that will call c.setOwner(newOwner) from itself (msg.sender = attacker)
        Attacker attacker = new Attacker(c);

        // Ensure ownerCandidate is funded so it can be tx.origin in a call sequence
        vm.deal(ownerCandidate, 1 ether);

        // Step 1: Make c.owner() == ownerCandidate by having ownerCandidate directly call setOwner on c
        // Only the true contract (reference) allows immediate caller == owner to set owner.
        vm.prank(ownerCandidate);
        bool okDirect;
        try c.setOwner(ownerCandidate) {
            okDirect = true;
        } catch {
            okDirect = false;
        }
        // If direct call by ownerCandidate failed to set owner, then ownerCandidate wasn't accepted as owner by c;
        // in that case the universal property we assert below is vacuously about the actual current owner in c.
        // For the property to be meaningful, ensure the direct call succeeded (this is wide and retains adversarial power).
        vm.assume(okDirect);

        // Confirm c.owner() is ownerCandidate now
        address currOwner = c.owner();
        assert(currOwner == ownerCandidate);

        // Now simulate a call where tx.origin == ownerCandidate but msg.sender == attacker (a contract)
        // The attacker contract will be invoked with tx.origin = ownerCandidate by using vm.prank(ownerCandidate)
        vm.prank(ownerCandidate);
        attacker.callSetOwner(newOwner);

        // The general rule (that the reference satisfies for all inputs): after the above sequence,
        // the owner should remain ownerCandidate unless the immediate caller was ownerCandidate (msg.sender == ownerCandidate).
        // Here the immediate caller was attacker (a contract), not ownerCandidate, so reference C must still have ownerCandidate.
        // The mutant using tx.origin would have changed owner to newOwner in this scenario for some inputs.
        assertTrue(c.owner() == ownerCandidate);
    }
}

// Minimal attacker contract: calls c.setOwner(newOwner) from itself (so msg.sender == address(this)), but the tx.origin
// will be the EOA that initiated the top-level call (set via vm.prank in the test). This distinguishes msg.sender vs tx.origin.
contract Attacker {
    C target;
    constructor(C _target) { target = _target; }
    function callSetOwner(address who) external {
        // forward the call to target; msg.sender here will be this contract
        target.setOwner(who);
    }
}

